export const GUIDE_CONTENT_B: Record<string, GuideSection[]> = {
  "finding-rental-canada": [
    { heading: "Where to Search", paragraphs: ["Kijiji: still the largest rental listing platform in Canada — set up instant email alerts. Rentals.ca: growing database of professional landlords and property managers, better filtering than Kijiji. Padmapper: maps listings from multiple platforms simultaneously for geographic browsing. Facebook Marketplace: often has private landlord listings before they reach major sites, particularly for basement suites and rooms. Your network: tell everyone — a significant portion of desirable rentals never get publicly listed. Craigslist: use with caution, higher scam rate than other platforms."], checklist: [] },
    { heading: "How to Stand Out as an Applicant", paragraphs: ["Prepare a complete rental application package before you start viewing: completed application form, free credit report pulled from Borrowell or Credit Karma, employment letter on company letterhead confirming salary and start date, two to three recent pay stubs, and two to three previous landlord references with direct phone numbers. Being the first applicant with a complete package often wins over a higher-income applicant who takes three days to respond. Landlords value certainty and speed."], checklist: [] },
    { heading: "Rental Scams to Avoid", paragraphs: ["Price below market for the area is the most reliable scam indicator. Never send a deposit before viewing the unit in person — no legitimate landlord requires this. A landlord who is 'abroad' and can only communicate by email is always a scam. Verify that the person showing the unit actually owns or manages it — search the property at your provincial land registry online. Never send money by wire transfer or cryptocurrency. Use certified cheque or e-transfer with a written receipt."], checklist: [] },
    { heading: "Negotiating Your Lease Terms", paragraphs: ["In a tight market, rent negotiation is difficult — but other terms are more flexible: move-in date (landlords prefer shorter vacancy periods and may offer concessions for quick move-in), lease term (month-to-month may be offered at slightly higher rent), utilities inclusion, and parking arrangement. In softer markets with longer vacancy times, rent itself becomes negotiable — especially for 12+ month fixed-term leases where the landlord values stability."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Set up daily alerts on Kijiji, Rentals.ca, and Padmapper", "Prepare full rental application package in advance", "Pull free credit report from Borrowell", "Get employment letter from employer on letterhead", "Collect 2–3 previous landlord references with phone numbers", "Always view unit in person before paying anything", "Verify landlord identity and property ownership", "Never send deposit before signing lease", "Document unit condition with photos immediately on move-in", "Email dated photos to landlord same day as move-in"] },
  ],
  "tenant-insurance": [
    { heading: "What Tenant Insurance Covers", paragraphs: ["Contents coverage: your furniture, electronics, clothing, bicycle, and personal belongings are protected if damaged by fire, water, or theft. Your landlord's building insurance covers the structure — it does not cover any of your personal property. Liability coverage: if you accidentally cause damage to the building (leaving the stove on, overflowing the bathtub) or injure a visitor, your liability coverage — typically $1M–$2M — pays for the damages and legal costs. Additional living expenses: if your unit becomes uninhabitable, tenant insurance pays for hotel and temporary accommodation during repairs."], checklist: [] },
    { heading: "What It Costs", paragraphs: ["Most tenant insurance policies in Canada cost $15–$40 per month — under $500 per year. For this you typically receive $30,000–$100,000 in contents coverage and $1M–$2M in liability. Factors affecting your premium: location, deductible amount, total contents value, and claims history. Get quotes from at least three insurers: Intact, Aviva, Wawanesa, Square One (excellent for renters), and your bank's insurance arm. Bundling with auto insurance often saves 5–15%."], checklist: [] },
    { heading: "Real Scenarios Where It Pays Off", paragraphs: ["Fire in a neighbouring unit spreads to yours and destroys your belongings — without insurance, you replace everything out of pocket. A pipe bursts above your unit and floods your space — your landlord's insurance covers their building; your insurance covers your damaged possessions and your hotel stay while repairs are done. You accidentally leave your stove element on and start a kitchen fire — liability coverage pays for the landlord's claim for building damage. Your laptop and camera are stolen from your vehicle — covered."], checklist: [] },
    { heading: "Getting the Right Coverage", paragraphs: ["Take a home inventory: video walk through every room narrating what you own and its approximate value. Store this video in cloud storage (not in your unit). Choose replacement cost coverage, not actual cash value — replacement cost pays what it costs to buy the item new today; actual cash value deducts depreciation and pays much less. For electronics, instruments, jewelry, or art, ask about scheduled items coverage for high-value pieces that exceed standard limits."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Get minimum 3 tenant insurance quotes", "Estimate total value of your contents", "Choose replacement cost over actual cash value", "Set deductible at an amount you can comfortably pay", "Document all belongings with video walk-through", "Store documentation in cloud, not in your unit", "Confirm liability coverage is at least $1M", "Check if bundling with auto insurance saves money", "Update coverage immediately if you acquire high-value items", "Provide proof of insurance to landlord if requested"] },
  ],
  "subletting-rights": [
    { heading: "What Subletting Means Legally", paragraphs: ["Subletting means you — the original tenant — rent your unit to a subtenant while you remain on the lease. You are still the tenant of record and remain fully responsible to the landlord: if the subtenant damages the unit or doesn't pay rent, you are liable. This is distinct from assignment, where you transfer your entire lease to a new tenant and exit the agreement. In Ontario, landlords cannot unreasonably withhold consent to subletting or assignment."], checklist: [] },
    { heading: "Rules by Province", paragraphs: ["Ontario: you have a legal right to sublet with the landlord's consent. The landlord may refuse only for reasonable cause (valid concerns about the subtenant). If the landlord refuses without cause, you can apply to the LTB. BC: you may sublet with the landlord's written consent; the landlord cannot arbitrarily refuse a suitable candidate. Alberta: requires landlord consent, but tenant protections on refusal are weaker — review your lease carefully and consult the RTDRS if refused."], checklist: [] },
    { heading: "How to Sublet Properly", paragraphs: ["Write a formal written request to your landlord describing who the subtenant is, the proposed dates, and confirming you remain responsible for the lease. Screen the subtenant as carefully as a landlord would: credit check, employment verification, and references. Sign a written sublease agreement with the subtenant — provincial LTB websites offer template sublease agreements. Collect first and last month's rent from the subtenant and hold it — do not spend it, as it may need to be returned."], checklist: [] },
    { heading: "Airbnb and Short-Term Rentals", paragraphs: ["Most standard leases prohibit short-term rental use including Airbnb and VRBO. Even where not explicitly prohibited by the lease, many condo corporations ban short-term rentals entirely, and most Canadian municipalities now have licensing requirements and principal-residence restrictions for STRs. The risks: lease termination, liability for noise complaints and property damage, bylaw fines, and potential liability for injuries to guests. Confirm your lease, condo rules, and municipal bylaws before listing any rental unit for short-term use."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Check your lease for subletting and assignment clauses", "Request subletting permission in writing from landlord", "Screen subtenant with credit check and references", "Prepare written sublease agreement", "Collect first and last month's rent from subtenant", "Confirm landlord's response within required timeframe", "Keep all communications in writing", "Check condo rules if in a condominium", "Verify municipal STR bylaws before any short-term use", "Remain responsible for lease throughout sublet period"] },
  ],
  "breaking-lease": [
    { heading: "Your Legal Options as a Tenant", paragraphs: ["Wait it out: if only a few months remain on the term, paying out may be simpler than the effort of finding a replacement. Sublet: find a subtenant to occupy the unit while you remain on the lease — you stay responsible but aren't paying rent without living there. Assignment: transfer your lease entirely to a new tenant (landlord must approve the new tenant but cannot unreasonably refuse a qualified candidate). Negotiate directly with your landlord: many will agree to an early termination if you find a suitable replacement, sometimes with a fee of one to two months' rent."], checklist: [] },
    { heading: "Valid Grounds for Early Termination Without Penalty", paragraphs: ["Ontario: you can terminate without penalty if your landlord has seriously violated your rights — illegal entry, failure to maintain, harassment. Domestic violence victims in most provinces can terminate with 28 days' notice and supporting documentation without penalty. Certain disability-related accommodations may also qualify. Job relocation is not a legal ground for penalty-free termination in most provinces — you remain financially responsible unless you arrange a replacement tenant or negotiate with your landlord."], checklist: [] },
    { heading: "Your Landlord's Duty to Mitigate", paragraphs: ["If you break your lease, your landlord is legally obligated to make reasonable efforts to re-rent the unit. If they find a new tenant quickly, your liability is limited to the vacancy period plus reasonable re-advertising costs. If the landlord deliberately leaves the unit vacant, you may not be liable for the full remaining rent — keep records of your efforts to assist with finding a replacement. In Ontario, the LTB governs disputes about mitigation and ongoing liability."], checklist: [] },
    { heading: "How to Leave Without Burning Bridges", paragraphs: ["Give maximum notice — even beyond what is legally required. Communicate everything in writing. Offer to help find a replacement tenant: post the listing yourself, show the unit to prospective tenants if the landlord permits. Leave the unit in excellent condition — document with photos on the final day. Maintaining the landlord's goodwill matters for references and may reduce any financial settlement they demand."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Review lease for early termination clause and penalties", "Calculate remaining months and total financial exposure", "Consider subletting or assignment before breaking lease", "Contact landlord in writing to discuss options", "Document all communications", "Offer to help find replacement tenant", "Give maximum possible written notice", "Clean and document unit condition at move-out", "Keep move-in photos to compare at departure", "Follow up on deposit return within legal timeframe"] },
  ],
  "disputing-rent-increase": [
    { heading: "Is Your Rent Increase Legal? Check These Four Things", paragraphs: ["1. Was it given in writing? Verbal notice, text messages, and emails without your lease agreement requiring email notice are invalid in most provinces. 2. Was enough notice given? Ontario requires 90 days written notice; BC requires 3 full months. 3. Is the percentage within the provincial guideline? Ontario's 2026 guideline is 2.5%; BC's is 3.0%. 4. Has it been at least 12 months since your last increase? If any of these four conditions isn't met, the increase is not valid and you are entitled to refuse payment of the excess."], checklist: [] },
    { heading: "Above-Guideline Increases: Your Rights", paragraphs: ["Landlords in Ontario can apply to the LTB for an above-guideline increase (AGI) for major capital expenditures (roof replacement, elevator repairs, new building systems) or extraordinary increases in municipal taxes or utilities. You will receive a copy of the application and have the right to attend a hearing and respond. Many AGIs are reduced or dismissed when tenants engage the process. Free tenant duty counsel is available at LTB hearings — use it. Common defences: the work wasn't necessary, costs were unreasonable, tenants didn't benefit."], checklist: [] },
    { heading: "What to Do If the Increase Is Illegal", paragraphs: ["Write to your landlord identifying the specific problem — improper form, insufficient notice, excess percentage, or inadequate notice period. Keep this letter. Pay only the legal amount: your existing rent plus the maximum legal percentage increase, properly notified. If the landlord insists you pay the full amount, file a T5 application with the LTB (illegal charge) — the filing fee is $53 and can result in a rent reduction order plus a rebate of any overpaid rent. Document all rent payments with date, amount, and method."], checklist: [] },
    { heading: "Protecting Yourself Going Forward", paragraphs: ["Maintain a complete rent payment log showing date paid, amount, and method of payment. Keep all rent receipts. Keep every version of your lease and any written communications from your landlord. If you are in a province without rent control (Alberta), negotiate a longer fixed-term lease when the rent level is favourable — it locks in your payment for the entire term. Know your LTB or equivalent tribunal's website and filing procedures before you need them."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Check 2026 guideline percentage for your province", "Verify written notice was provided on correct form", "Confirm 90-day notice period was met", "Confirm 12+ months since last increase", "Calculate maximum legal increase amount", "Write to landlord if any requirement unmet", "Pay only the legally valid amount", "File LTB T5 application if landlord insists", "Attend any LTB hearing with full documentation", "Maintain running rent payment log going forward"] },
  ],
  "roommate-agreement": [
    { heading: "Financial Responsibilities", paragraphs: ["Document in writing: who pays what portion of rent and how (does one person pay the landlord and collect from others, or does each pay their share directly?). Utilities: split equally or proportionally by room size? Who sets up each account and whose name is on it? Household supplies (cleaning products, toilet paper, shared kitchen staples): shared fund or individual? A household fund of $50–$100/month each works well for most households. Document how much each person contributed to the damage deposit and how it will be divided at move-out."], checklist: [] },
    { heading: "House Rules", paragraphs: ["Quiet hours: agree on specific times (10pm weeknights, midnight on weekends is a common baseline). Overnight guests: for how many consecutive nights before it becomes a co-tenancy issue? Cleaning: divide specific chores or rotate on a schedule — write it down and post it. Kitchen: label food, clean up the same day, dishes done within 24 hours. Common areas: defined expectations for cleanliness and shared use. Smoking, cannabis, pets (if permitted by the lease): agree on specific rules and locations."], checklist: [] },
    { heading: "If Someone Leaves", paragraphs: ["Notice period: agree everyone gives 60 days notice to other roommates — matching the notice you'd give a landlord — so no one is scrambling. Replacement tenants: does everyone have veto rights over a replacement? Who screens candidates? Costs: who covers the departed roommate's share during a vacancy before a replacement arrives? In a joint tenancy (all names on the lease), all remaining tenants are 100% liable for the full rent — one person leaving doesn't reduce the others' obligations."], checklist: [] },
    { heading: "Legal Framework", paragraphs: ["A roommate agreement is not the same as a lease. The crucial question is whose name appears on the original lease. If only one name is on the lease, the other roommates are subtenants with limited legal protections — the primary tenant has significant power. If all names are on the lease as joint tenants, everyone has equal rights and equal obligations. Adding roommates to the lease gives them more protection but also makes them equally liable for the full rent and any damages."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Agree on rent split before signing anything", "Document utility account setup and responsibilities", "Set up shared household expense fund", "Agree on quiet hours and guest policy", "Define cleaning responsibilities in writing", "Agree on 60-day departure notice requirement", "Define replacement tenant process and approval", "Confirm who is on the lease and their legal status", "Sign and date the agreement — both keep copies", "Review and update agreement annually or when a roommate changes"] },
  ],
  "moving-out-checklist": [
    { heading: "Notice Requirements by Province", paragraphs: ["Most provinces require 60 days written notice to vacate — either at the end of a fixed term or at any point during a monthly tenancy. In Ontario, use Form N9 and give it on or before the first day of the month to be effective for the last day of the following month. In BC, one full rental period's notice (typically one month) is required. Give notice in writing; email is generally acceptable but registered mail provides the strongest proof. Start your notice period countdown from the correct date — errors cost an extra month."], checklist: [] },
    { heading: "Cleaning Standards Required", paragraphs: ["Landlords expect the unit returned in the condition it was received, minus normal wear and tear. Normal wear and tear includes: small scuff marks, minor carpet wear from regular use, faded paint. Your responsibility includes: holes in walls (from picture hooks, anchors, or shelf brackets), major stains, burn marks, or damage beyond normal use. Clean: inside the oven and fridge, all bathroom surfaces, inside every cupboard, baseboards, windows, light fixtures, and window tracks. Budget $200–$400 for a professional cleaner if you're not confident — it's cheaper than losing your deposit."], checklist: [] },
    { heading: "Documenting Your Move-Out", paragraphs: ["Compare your original move-in photos directly against the current condition. Photograph every room, every wall surface, inside every appliance, and all fixtures. Time-stamp every photo. Request a joint walkthrough with your landlord on or before your final day — any agreement on condition should be in writing immediately after. If your landlord isn't available for a joint walkthrough, email all dated photos to the landlord on the day you vacate and keep the sent confirmation."], checklist: [] },
    { heading: "Your Deposit Return Rights", paragraphs: ["Ontario: landlords are not permitted to charge a damage deposit beyond first and last month's rent. Your last month's rent is your security. BC: landlord must return your deposit within 15 days of the end of tenancy or dispute it within that window — failure automatically entitles you to double the deposit. Alberta: landlord must inspect within 3 business days of move-out and provide an itemized statement within 10 days. In all provinces, demand a specific itemized list for any deductions — 'general cleaning' or 'damage' without specifics is inadequate."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Give written notice on correct date (60 days minimum)", "Use correct provincial form (N9 in Ontario)", "Compare move-out condition to original move-in photos", "Deep clean entire unit including inside appliances", "Repair all holes and damage beyond normal wear", "Photograph every room and surface on final day", "Email dated photos to landlord immediately on vacating", "Return all keys, fobs, and access cards", "Provide forwarding address for deposit return", "Request itemized deduction list if any amount is withheld", "File LTB or RTDRS application if deposit wrongly kept"] },
  ],
  "rent-affordability": [
    { heading: "The 30% Guideline and Its Limits", paragraphs: ["The 30% of gross income rule originated in 1960s American housing policy and doesn't reflect Canadian urban reality. In Toronto, average one-bedroom rent exceeds $2,200/month. Keeping that to 30% of gross income requires earning $88,000/year. Median individual income in Toronto is significantly below this. In practice, many Toronto and Vancouver renters spend 35–45% of income on housing and manage it by carefully controlling all other expenses. The goal is a sustainable total budget — not arbitrary adherence to a percentage."], checklist: [] },
    { heading: "A More Useful Framework: Net Income Ratio", paragraphs: ["Calculate your net take-home pay rather than gross. Housing cost divided by net income is a more actionable number. If your take-home is $4,200/month, $1,400 in rent is 33% of net — comfortable. $1,900 is 45% of net — tight but manageable if you have no car payment and low other debt. The absolute floors you must protect regardless of rent: emergency fund (3–6 months of expenses), RRSP or TFSA retirement contributions, and not carrying high-interest credit card debt. If paying rent prevents all three, you need a cheaper unit."], checklist: [] },
    { heading: "Practical Strategies to Reduce Housing Cost", paragraphs: ["Roommates: splitting a two-bedroom at $2,800 total costs $1,400 each — significantly less than a one-bedroom alone at $2,200 and you typically get more space. Neighbourhood tradeoffs: 2–3 stops further on transit saves $300–$500/month in many markets — calculate the commute cost carefully. Negotiate: offer a 24-month fixed lease in exchange for stable rent — many landlords accept stability over a higher rate. Basement suites typically rent 20–30% below comparable above-grade units. Brampton, Mississauga, Hamilton, Burnaby, Surrey, and Laval all offer substantially lower rents than their core cities."], checklist: [] },
    { heading: "When to Consider Buying Instead of Renting", paragraphs: ["Rent vs buy is a personal calculation that depends on your specific income, savings, stability, and local market. Generally worth running the numbers when: your rent exceeds $2,000/month and you could qualify for a mortgage; you plan to stay in the same city for 5+ years; you have at least 5% saved plus closing costs; and you have stable employment. $2,200/month in rent over 5 years is $132,000 spent with zero equity accumulated. A modest purchase, even accounting for all carrying costs, typically builds meaningful equity over the same period."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Calculate rent as percentage of net take-home income", "Confirm rent leaves room for emergency fund contributions", "Confirm rent leaves room for RRSP/TFSA contributions", "Explore roommate option to reduce per-person cost", "Compare rents in adjacent neighbourhoods before committing", "Negotiate longer lease term in exchange for rate stability", "Never carry high-interest debt to afford rent", "Calculate rent vs buy comparison at current mortgage rates", "Track all housing costs: rent, utilities, tenant insurance, parking"] },
  ],
  "landlord-tax-deductions": [
    { heading: "Fully Deductible Current Expenses", paragraphs: ["Mortgage interest (not the principal portion — only the interest component). Property taxes. Building insurance premiums. Repairs and maintenance that restore but don't improve the property. Property management fees. Advertising costs (rental listings, photography). Legal fees for lease preparation or tenant disputes. Accounting fees related to the rental. Travel to inspect or maintain the property (CRA mileage rate). Utilities you pay on behalf of tenants. Office expenses for managing the rental property. All expenses require receipts — use a dedicated folder by tax year."], checklist: [] },
    { heading: "Capital Cost Allowance (CCA)", paragraphs: ["CCA is a depreciation deduction on the building structure (not the land). For most residential rental properties (Class 1), the rate is 4% declining balance annually. CCA reduces your taxable rental income while you own the property — but it triggers recapture when you sell, meaning you are taxed on the amount you previously deducted. Generally advisable for higher-income landlords who benefit most from the current deduction. Important constraint: you cannot claim CCA to create or increase a rental loss — only to reduce rental income to zero."], checklist: [] },
    { heading: "What Is Not Deductible", paragraphs: ["The principal portion of your mortgage payments — only the interest component is deductible. Personal use portions of expenses: if you rent one room in your primary home, only the proportionate square footage percentage of expenses is deductible. Land value in the purchase price: only the building is depreciable, not the land. Capital improvements (adding a bathroom, finishing the basement, new kitchen) — these are added to the property's adjusted cost base, not expensed immediately. Losses from arrangements that are not commercial in nature."], checklist: [] },
    { heading: "Record-Keeping for CRA Compliance", paragraphs: ["CRA requires you to keep all supporting documents for 6 years from the end of the tax year they relate to. Keep: bank statements showing all rent received, all expense receipts with date, vendor name, amount, and purpose, your lease agreements, insurance policies, and T776 filed returns. Open a dedicated bank account and credit card exclusively for the rental property — this makes annual accounting dramatically simpler and is considered best practice by most real estate accountants."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Open dedicated bank account for rental income and expenses", "Collect and store all receipts with date, vendor, purpose", "Separate mortgage interest from principal on statements", "Track all property tax and insurance premium payments", "Document all repairs vs capital improvements (different tax treatment)", "Record all mileage for property-related travel", "File Schedule T776 annually with personal tax return", "Discuss CCA decision with accountant each year", "Maintain 6 years of complete records", "Consider accounting software (Wave, QuickBooks) for multi-unit owners"] },
  ],
  "above-guideline-rent": [
    { heading: "Valid Grounds for an AGI Application", paragraphs: ["Major capital expenditures (MCEs): significant capital replacements benefiting tenants — new roof, elevator modernization, building envelope repairs, boiler replacement, underground parking remediation. Extraordinary increases in municipal taxes or utilities that the landlord pays directly. Security services costs not previously included in rent. Routine repairs and general maintenance do not qualify — the work must be capital in nature, replacing rather than maintaining. The threshold and per-unit cost allocation formulas are set by the LTB."], checklist: [] },
    { heading: "The Application Process", paragraphs: ["File an L5 application at the Landlord-Tenant Board (online at ontario.ca/LTB). Include all supporting documentation: contracts and invoices for capital work, property tax statements, utility bills showing extraordinary increases. All affected tenants receive notice of the application and have the right to file a response and attend a hearing. The LTB reviews the application and issues an order specifying the approved increase amount — which may be less than applied for. Approved AGIs are typically amortized over three years."], checklist: [] },
    { heading: "What Tenants Can Challenge", paragraphs: ["Tenants frequently challenge AGIs on the basis that: the capital work was not necessary or could have been avoided with proper maintenance, the costs claimed were not reasonable or competitive, the tenants did not sufficiently benefit from the improvement, or the per-unit allocation method was incorrect. Many AGI applications are reduced at hearing when tenants engage. Landlords who proceed without proper documentation and legal advice frequently see significant reductions in the approved amount."], checklist: [] },
    { heading: "Strategic Considerations", paragraphs: ["AGI applications are time-consuming, contentious, and expensive — budget $3,000–$8,000 in legal and filing costs including paralegal representation. For large buildings with significant capital work ($500,000+), the per-unit increase often justifies the process. For small landlords with one to four units, major capital expenses may be better managed through purchase price negotiation (if you knew before buying) or direct negotiation with a long-term tenant. Always consult an LTB-experienced paralegal before filing."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Confirm capital work qualifies under LTB guidelines", "Gather all invoices and contracts with dates", "Calculate per-unit cost allocation accurately", "Consult LTB paralegal before filing", "File L5 application with complete supporting documentation", "Serve required tenant notice simultaneously", "Prepare for hearing — bring all original invoices", "Understand 3-year amortization of approved increase", "Update rent ledgers immediately after order issued", "Note next allowable rent increase date for each unit"] },
  ],
  "condo-rental-rules": [
    { heading: "The Condo Corporation's Authority Over Your Tenants", paragraphs: ["Condo corporations can restrict and regulate: short-term rentals, pets, parking use, move-in and move-out times and procedures, amenity use, noise, and number of occupants. These rules bind you as the owner and they bind your tenants. You are responsible for your tenant's compliance with condo rules — you cannot disclaim responsibility simply because you weren't present. Violations by your tenant can result in fines to you, legal action from the corporation, and potentially mandatory compliance orders."], checklist: [] },
    { heading: "Short-Term Rental Restrictions", paragraphs: ["The majority of Toronto and Vancouver condo corporations now explicitly prohibit rentals shorter than 28 or 30 days. Municipal licensing requirements are tightening further — in Toronto, only your principal residence can be rented short-term. As a non-resident investor-landlord, short-term rental platforms are effectively not a viable strategy in most condo buildings built in the last decade. Check the declaration and rules before purchasing any condo with short-term rental income in mind — many declarations simply prohibit it."], checklist: [] },
    { heading: "Your Compliance Obligations as Landlord", paragraphs: ["Include the full set of condo rules and the condo declaration as a schedule to your lease — tenants must explicitly agree to comply. Notify the condo corporation of your tenant's contact information as required by the Condominium Act. Respond promptly to any complaints from the property manager about your tenant's behaviour. You can be fined for your tenant's violations of condo rules — build this risk into your investment assessment. Repeated rule violations by a tenant may constitute grounds for eviction based on interference with others' reasonable enjoyment."], checklist: [] },
    { heading: "Status Certificate Review Before You Buy", paragraphs: ["Before purchasing any condo as a rental investment, have a lawyer review the status certificate: Is the reserve fund adequately funded relative to the reserve fund study? Are there pending or anticipated special assessments? What do the rules say explicitly about rentals, short-term use, and rental caps? Is there a maximum percentage of units that can be rented (some corporations cap at 20–30%)? A rental cap that has been reached means you legally cannot rent the unit — a catastrophic discovery after purchase."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Review full condo declaration and rules before purchasing", "Confirm no rental cap or that cap is not reached", "Check short-term rental prohibition explicitly", "Include condo rules as signed schedule in tenant lease", "Register tenant contact info with condo corporation", "Introduce yourself to property manager before tenancy starts", "Respond to all corporation complaints within 24 hours", "Keep copy of all condo rules and declaration", "Review status certificate with lawyer before buying", "Check municipal STR licensing requirements in your city"] },
  ],
  "landlord-insurance": [
    { heading: "Why Standard Home Insurance Fails for Rentals", paragraphs: ["Standard homeowner's and condo owner's insurance covers owner-occupied properties. The moment a tenant occupies the property, most policies either explicitly exclude coverage or consider the policyholder in breach of the terms — voiding coverage entirely. An insurance claim after a tenant-caused fire or flood, with no valid policy, can leave you personally liable for hundreds of thousands of dollars in uninsured losses. This is not a theoretical risk: insurers regularly deny claims when they discover the property was occupied by a tenant."], checklist: [] },
    { heading: "What Landlord Insurance Covers", paragraphs: ["Building coverage: the structure, systems, and landlord-owned fixtures against fire, flood, wind, vandalism, and other insured perils. Loss of rental income: if the unit becomes uninhabitable due to an insured event, this covers your lost rent during the repair period — typically 12–24 months. Liability: if a tenant or visitor is injured on your property, liability coverage (typically $1M–$5M) covers legal costs and damages. Legal expenses: some policies include coverage for LTB applications, eviction proceedings, and tenancy dispute legal costs — this rider is worth the premium."], checklist: [] },
    { heading: "Tenant-Caused Damage", paragraphs: ["If a tenant causes damage through negligence (overflow, fire) or intentionally, your landlord insurance may cover you less your deductible. You then pursue the tenant through the LTB for the deductible amount and any uncovered costs. Requiring tenants to carry their own tenant insurance and including this requirement in the lease ensures tenants have liability coverage. Some landlord policies include malicious damage riders — worth the added premium for landlords who have experienced tenant damage. Confirm your policy covers tenant-caused damage specifically."], checklist: [] },
    { heading: "Getting the Right Policy", paragraphs: ["Get quotes from: Intact, Wawanesa, RSA, Gore Mutual, and Square One (particularly strong for rental condos). Tell your broker exactly how the property is used — long-term residential rental, room rental, multi-unit residential — and ensure the policy reflects actual use. Critical questions: Is loss of rental income included and for how long? What is the vacancy clause — policies often exclude coverage if vacant more than 30 consecutive days (important between tenancies)? Is sewer backup covered? What is the claims process and your deductible?"], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Cancel or convert existing homeowner policy before tenant moves in", "Get landlord insurance active before occupancy begins", "Confirm coverage: building, liability, loss of rental income", "Check vacancy clause — know your maximum vacancy window", "Ask about malicious damage rider", "Add legal expense rider if available", "Require tenants to carry tenant insurance — include in lease", "Keep policy current with accurate property use description", "Photograph property condition thoroughly before each tenancy", "Know your insurer's claims contact before you ever need it"] },
  ],
  "lease-renewal": [
    { heading: "What Happens When a Fixed Term Ends", paragraphs: ["In Ontario (and most provinces), when a fixed-term lease expires and neither party takes action, it automatically converts to a monthly periodic tenancy on identical terms. The tenant has the right to remain. You cannot require a tenant to sign a new lease — they can remain on month-to-month indefinitely. You cannot evict a tenant simply because the fixed term ended — a valid legal ground is required regardless of tenancy type. This surprises many landlords who assume the lease end gives them back the property."], checklist: [] },
    { heading: "Renewal Options and How to Execute Them", paragraphs: ["Sign a new fixed-term lease: both parties agree to a new term in writing — provides stability and a clear new rent level. Move to month-to-month: simpler and more flexible for both parties — often the default in long-standing tenancies. Offer a rent increase with renewal: you can increase rent only once per 12 months with proper 90-day written notice (Ontario). Signing a new lease is an opportunity to set a new rent level with the tenant's explicit written agreement — no N1 form required if the new rent is documented in the signed lease."], checklist: [] },
    { heading: "Ending the Tenancy Legally", paragraphs: ["Valid grounds to terminate tenancy include: landlord's own use (you, your child, or parent intends to occupy — N12 in Ontario, 60 days notice plus one month's rent compensation), sale to a buyer who intends to occupy (N12 served by the buyer), or significant renovation requiring vacant possession (N13, 120 days notice plus right of first refusal). Filing an N12 in bad faith — without genuine intention to occupy — exposes you to significant LTB penalties including large rent abatement awards. Document your genuine intention thoroughly."], checklist: [] },
    { heading: "Incentivizing a Good Tenant to Renew", paragraphs: ["A reliable, long-term tenant is worth more than a fresh tenancy with an unknown person. Consider: offering a below-guideline increase as a goodwill gesture on renewal, completing agreed repairs or improvements as part of the renewed relationship, or offering a two-year fixed term with rent certainty for both sides. The cost of one bad tenancy — LTB proceedings, lost rent, unit damage, reletting costs — typically exceeds 12–18 months of below-market rent to a good tenant. Factor this into your renewal calculus."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Review lease end date at least 90 days in advance", "Decide: new fixed term, month-to-month, or end tenancy", "Prepare new lease or written rent agreement for renewal", "Confirm 12+ months have passed since last rent increase", "Send N1 form for guideline increases with 90 days notice", "Discuss renewal with tenant face to face or in writing early", "If ending tenancy, confirm valid legal ground exists", "Serve correct notice form with full required notice period", "Document all agreements in writing and keep copies", "Update rent ledger with new amount and effective date"] },
  ],
  "property-management-diy": [
    { heading: "Rent Collection System", paragraphs: ["Set up pre-authorized e-transfer or automated bank payment — eliminates late-payment excuses and creates an automatic digital record. Rent is due the first; send a friendly payment reminder on the 28th. If payment hasn't arrived by the 5th, follow up in writing immediately. In Ontario, if rent is unpaid by the 14th, serve Form N4 that day — do not wait and hope. Every day you delay adds cost. Document every payment received with date and amount in a simple spreadsheet or property management software."], checklist: [] },
    { heading: "Maintenance System", paragraphs: ["Respond to every maintenance request in writing within 24 hours — even if the repair takes longer, the acknowledgement matters. Maintain a list of reliable, responsive trades: licensed plumber, electrician, HVAC technician, and a general handyman. Failure to maintain the property to health and safety standards is grounds for a tenant rent abatement application at the LTB — deferred maintenance always costs more than timely repairs, both financially and legally. Track all maintenance requests and repairs in writing."], checklist: [] },
    { heading: "Annual Inspections", paragraphs: ["You are legally entitled to inspect your rental property with 24 hours written notice. Schedule an annual inspection — use it to identify developing maintenance issues before they become expensive, confirm no lease violations (unauthorized pets, subletting, damage), and maintain a professional working relationship with the tenant. Bring a written inspection checklist, note all observations, leave a copy with the tenant. Professional and respectful inspections build trust; invasive or confrontational ones create enemies."], checklist: [] },
    { heading: "When to Hire a Property Manager", paragraphs: ["Seriously consider professional management when: you own three or more units, you live more than 45 minutes from the property, you travel frequently and cannot reliably respond to emergencies, you have had a difficult tenancy that required LTB proceedings, or your time is genuinely worth more than the management fee. A good property manager pays for themselves in avoided vacancies, better tenant selection, faster maintenance resolution, and reduced legal risk. Interview three managers, check references, and review the management agreement carefully before signing."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Set up pre-authorized rent collection", "Create rent payment tracking spreadsheet", "Build list of at least 4 trusted trades", "Respond to all maintenance requests in writing within 24 hours", "File N4 on day 14 if rent is unpaid — no exceptions", "Schedule annual inspection with proper written notice", "Document all communications with tenants", "Keep all maintenance records with dated invoices", "File T776 with personal tax return annually", "Calculate honestly when management fee becomes worthwhile"] },
  ],
  "tenant-screening": [
    { heading: "The Complete Application Package", paragraphs: ["Require a written rental application from every prospective tenant. It must include: full legal name, current and previous addresses for the past two years, employer name, address, and supervisor contact, employment income information, written consent to a credit check, two previous landlord references with direct phone numbers (not email), and two personal references. An applicant who refuses to provide any element of this standard package before viewing or applying is a red flag — legitimate tenants understand and accept this process."], checklist: [] },
    { heading: "Credit Check Best Practices", paragraphs: ["Pull a formal credit report from Equifax or TransUnion with the applicant's written consent — verbal consent is insufficient for PIPEDA compliance. Review: overall score (680+ strong, 600–679 proceed with caution, below 600 requires significant other evidence), payment history (missed payments, collections, judgments), total existing debt load relative to income, and any prior eviction orders or judgments. Provide a copy to the applicant as required. A lower score from one-time medical debt is different from a pattern of missed bill payments — read the full report, not just the number."], checklist: [] },
    { heading: "Reference Checks That Actually Reveal Information", paragraphs: ["Call previous landlords directly — written letters can be fabricated. Key questions: How long was the tenancy? Did they pay rent on time consistently? What was the condition of the unit at move-out? Would you rent to them again without hesitation? A previous landlord who gives short, evasive answers, takes a long pause before 'would you rent again,' or offers faint praise ('they were fine') is signalling a problem they don't want to state directly. The question 'without hesitation' matters — note the pause."], checklist: [] },
    { heading: "Legal Limits on Screening", paragraphs: ["The Human Rights Code prohibits refusing a tenant on the basis of: race, ancestry, place of origin, colour, ethnic origin, citizenship, religious creed, sex, sexual orientation, gender identity, age (18+), marital status, family status, disability, or receipt of public assistance (in most provinces). You cannot refuse a tenant because they have children, are on ODSP or Ontario Works, are a visible minority, are LGBTQ+, are from another country, or are pregnant. You can and must screen on financial qualifications, rental history, and references. Document your screening reasons — always financial and factual, never personal."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Create standardized rental application form", "Pull credit report with written consent from every applicant", "Call previous landlords directly — never accept written letters only", "Verify employment by calling employer directly", "Search CANLII for prior LTB orders against the applicant", "Ask 'would you rent again without hesitation?' — listen carefully", "Apply identical screening criteria to every applicant", "Document specific reasons for rejection (financial only)", "Keep all applications and screening records for 12 months", "Never ask about protected characteristics at any stage"] },
  ],
  "eviction-notices": [
    { heading: "N4 — Non-Payment of Rent", paragraphs: ["Use when: rent has not been paid in full by the date due. The N4 must state: the exact amount owed, the period it covers, and the termination date (14 days from service). The monetary amount must be exactly correct — even a $1 error results in dismissal. After the 14-day period, if rent remains unpaid, file an L1 application with the LTB. The N4 becomes void only if the tenant pays the full amount stated within the 14 days. Do not include any amount other than unpaid rent on the N4 — NSF fees, utilities, or other charges belong on different forms."], checklist: [] },
    { heading: "N5 — Interference with Reasonable Enjoyment or Damage", paragraphs: ["Use when: tenant is causing wilful or negligent damage to the property, or substantially interfering with others' reasonable enjoyment through persistent noise, parties, smoke, or similar conduct. First N5: gives the tenant 20 days to correct the behaviour. If the behaviour stops and does not recur within 6 months, the N5 is void. If behaviour continues during the 20 days OR recurs within 6 months of the first N5, serve a second N5 — which gives no correction period — and immediately file an L2 application. Document every incident with dates, times, descriptions, and any witnesses."], checklist: [] },
    { heading: "N12 — Landlord's Own Use", paragraphs: ["Use only when: you, your spouse, a child, or a parent genuinely intends to move into the unit and occupy it as their principal residence. Requires: 60 days written notice ending on the last day of a rental period. One month's rent compensation payable on or before the termination date — payable to the tenant whether or not they vacate. If the named person does not actually move in within a reasonable time after possession, the tenant can apply for a bad faith finding resulting in significant penalties — documented cases show awards of 12 months' rent. Only serve an N12 when the intention to occupy is completely genuine."], checklist: [] },
    { heading: "Serving Notices Correctly", paragraphs: ["Ontario permits service by: hand delivery (most reliable), registered mail (add 5 days to notice period), courier, posting on the unit door after attempting delivery, or by email if the tenant has explicitly agreed in writing to receive notices electronically. For every notice served, complete a Certificate of Service documenting the date, method, and any witnesses. LTB adjudicators require this at hearings. Improper service — wrong method, insufficient notice, or no certificate — results in the notice being set aside and the process starting over from day one."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Use exact correct LTB form for each situation", "Calculate notice periods precisely — errors restart the process", "Verify monetary amounts on N4 are exactly correct", "Confirm termination date falls on last day of a rental period", "Complete Certificate of Service for every notice", "File L1 or L2 only after notice period has fully expired", "Bring original lease, rent ledger, and all notices to every hearing", "For N5: document each incident with date, time, description", "For N12: document genuine occupancy intention thoroughly", "Pay N12 one-month compensation on or before termination date"] },
  ],
  "real-estate-glossary": [
    { heading: "A–D", paragraphs: ["Abatement: a reduction in rent or purchase price for a specific reason. Amortization: total repayment period for a mortgage (typically 25 or 30 years). Assessment: municipal valuation of a property for tax purposes. Bully offer: an offer submitted before the scheduled offer review date, with a short irrevocable period to pressure the seller. Bridge financing: short-term loan covering the gap between buying a new home and selling an existing one. Buyer's agent: a real estate agent whose fiduciary duty runs to the buyer. Cap rate: net operating income divided by property value — used for investment property analysis. Chattel: movable personal property (appliances, window coverings) that may or may not be included in a sale. Closing: the date legal ownership transfers. CMA: Comparative Market Analysis — agent analysis of recent sold data. Condition: a clause requiring a specified event before the deal becomes firm."], checklist: [] },
    { heading: "E–L", paragraphs: ["Easement: legal right of one party to use part of another's property (e.g. utility easement, right of way). Equity: property value minus outstanding mortgage balance. Escalation clause: offer clause automatically beating competing offers by a set amount up to a ceiling. Estoppel certificate: condo document confirming current fees and legal status. Firm deal: all conditions have been waived — the sale is legally binding. GDS: Gross Debt Service ratio (housing costs / gross income, max 32%). High-ratio mortgage: down payment under 20% — CMHC insurance required. Holdback: funds withheld after closing pending completion of agreed repairs. Irrevocable period: window during which an offer cannot be withdrawn. LTV: Loan to Value ratio (mortgage / property value). Latent defect: hidden defect not discoverable on reasonable inspection — must be disclosed by seller."], checklist: [] },
    { heading: "M–R", paragraphs: ["Market value: price a willing buyer and seller would agree on in an arm's length transaction. Maturity date: end of a mortgage term — must renew, refinance, or pay off. MPAC: Municipal Property Assessment Corporation (Ontario). MLS: Multiple Listing Service — database of listed properties shared among REALTOR® members. NOA: Notice of Assessment — annual CRA document confirming your filed income. Open mortgage: can be repaid in full at any time without penalty (carries higher rate). Patent defect: visible defect observable on reasonable inspection. Portability: ability to transfer your existing mortgage to a new property without penalty. Prepayment privilege: annual right to make extra principal payments without penalty. PRE: Principal Residence Exemption — tax exemption on capital gain from your home. Quiet enjoyment: tenant's right to use their unit without unreasonable landlord interference."], checklist: [] },
    { heading: "S–Z", paragraphs: ["Schedule A: additional terms appended to an Agreement of Purchase and Sale. Seller's market: demand exceeds supply — sellers have pricing power and typically receive multiple offers. Status certificate: condo document with financial statements, reserve fund study, rules, and litigation history. Stress test: federal mortgage qualifying test — must qualify at contract rate + 2% or 5.25%, whichever is higher. TDS: Total Debt Service ratio (all debts / gross income, max 44%). Title: legal ownership of real property registered at the Land Registry. Title insurance: policy covering title defects, survey issues, zoning violations, and title fraud. Vendor take-back mortgage: seller provides financing to buyer as part of the transaction. Working with a REALTOR®: disclosure document explaining the agency relationship — required by RECO in Ontario."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Bookmark this page for reference throughout your transaction", "Review unfamiliar terms before signing any document", "Ask your agent or lawyer to clarify any term you don't understand", "Return to this glossary at each new stage of the process"] },
  ],
  "fhsa-rrsp-combo": [
    { heading: "The Combined Maximum", paragraphs: ["First Home Savings Account (FHSA): contribute up to $8,000/year to a lifetime maximum of $40,000. Contributions are tax-deductible; qualifying withdrawals for a first home purchase are completely tax-free with no repayment obligation. RRSP Home Buyers' Plan (HBP): withdraw up to $35,000 per person ($70,000 per couple) from your RRSP tax-free. Must be repaid over 15 years or the annual shortfall is added to your taxable income. Combined maximum for a single buyer: $40,000 FHSA plus $35,000 RRSP HBP equals $75,000 — all received tax-free, with no repayment on the FHSA portion."], checklist: [] },
    { heading: "The Order of Operations", paragraphs: ["Always maximize the FHSA first — the absence of any repayment obligation makes it strictly superior dollar-for-dollar compared to the RRSP HBP. FHSA contributions are deductible like an RRSP and withdrawals are tax-free like a TFSA — it combines the best feature of each. After maximizing your FHSA, contribute to your RRSP for the HBP. If you already have RRSP savings from previous years, you can use those too — existing RRSP funds just need to have been in the account for 90 days before withdrawal."], checklist: [] },
    { heading: "Key Rules for Both Programs", paragraphs: ["FHSA: must be open for at least one full calendar year before making a qualifying withdrawal. RRSP HBP: funds must be in the RRSP for a minimum of 90 days before withdrawal under the HBP. Both: you must be a first-time buyer for both programs — defined as not having owned a principal residence that you lived in at any time during the current year or the preceding 4 calendar years. Both withdrawals must be made before October 1 of the year following the year you first occupied the home."], checklist: [] },
    { heading: "The Real Tax Savings", paragraphs: ["Example at a 40% combined marginal tax rate: contributing $40,000 to your FHSA generates a $16,000 tax refund. Contributing $35,000 to your RRSP generates a $14,000 refund. Total tax refunds: $30,000 — which can be redirected back into more savings. The FHSA $40,000 is then withdrawn tax-free (no repayment ever). The RRSP $35,000 is withdrawn tax-free with a $2,333/year repayment schedule over 15 years. Effective government subsidy on your down payment: substantial."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Confirm first-time buyer eligibility for both programs", "Open FHSA immediately if not already open", "Maximize FHSA contributions ($8,000/year, $16,000 max with carry-forward)", "Ensure RRSP funds sit for 90+ days before HBP withdrawal", "Keep FHSA open for at least one full calendar year", "Apply FHSA withdrawal first (no repayment)", "Supplement with RRSP HBP if needed", "Track HBP repayment schedule — begins 2 years after withdrawal year", "File correct CRA forms: RC725 (FHSA), T1028 (HBP)", "Discuss strategy timeline with mortgage broker"] },
  ],
  "rent-vs-buy": [
    { heading: "The True Cost of Buying", paragraphs: ["Purchase price is just the beginning. Add: CMHC insurance premium (if down payment under 20%), land transfer tax, legal fees, home inspection, moving costs, and initial repairs and updates. Then ongoing: mortgage payment (principal + interest), property tax, home insurance, maintenance (budget 1%–2% of home value annually — $7,000–$14,000/year on a $700,000 home), and any condo maintenance fees. The first 1–3 years of homeownership are typically the most expensive relative to renting equivalent space."], checklist: [] },
    { heading: "The True Cost of Renting", paragraphs: ["Monthly rent plus tenant insurance ($15–$40/month) plus parking if not included. The key renting advantage: full flexibility. No maintenance obligations. No property value risk. Capital that would be tied up in a down payment can be invested. The key renting disadvantage: no equity building, no inflation protection on housing costs long-term, and the real risk of rent increases or landlord's own use situations displacing you at inconvenient times. Rent control provides partial protection in Ontario and BC; Alberta has none."], checklist: [] },
    { heading: "The Break-Even Timeline", paragraphs: ["Buying generally becomes financially superior to renting after 5–7 years in most Canadian markets, assuming average historical appreciation. Before that point, transaction costs (LTT, legal fees, commission when you sell) can exceed any equity gains in flat or slow markets. If you are confident you will stay in the same city for 5+ years and your income is stable, buying generally makes long-term financial sense. If you expect to move within 3 years, renting preserves flexibility that buying destroys."], checklist: [] },
    { heading: "The 2026 Specific Context", paragraphs: ["Falling interest rates are improving mortgage affordability. The FHSA gives first-time buyers up to $40,000 in government-subsidized down payment. 30-year amortization for first-time buyers of new builds further reduces monthly payments. Condo prices in Toronto and Vancouver have softened — buyers have more negotiating room than in 2021–2022. Rents in major cities remain very high — often $2,000–$2,800 for a one-bedroom. In many situations, the monthly cost of owning a similar space is now closer to the monthly cost of renting than it has been in several years."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Calculate true monthly cost of buying (mortgage + tax + insurance + maintenance)", "Calculate true monthly cost of renting equivalent space", "Determine your likely tenure in this city (5+ years = buying stronger case)", "Calculate total transaction costs of buying now and selling in 3 years", "Calculate FHSA + RRSP HBP available down payment", "Run mortgage qualification stress test", "Factor job stability and income trajectory honestly", "Consult a fee-only financial planner for personal analysis", "Make the decision based on your specific numbers, not general advice"] },
  ],
  "power-of-sale-foreclosure": [
    { heading: "Power of Sale: How It Works", paragraphs: ["Power of sale is the more common remedy in Ontario and most common-law provinces. The lender sells the property without taking ownership — proceeds go to pay off the mortgage, with any surplus returned to the borrower. The lender must: provide notice of sale, advertise the property, obtain a fair market value (confirmed by appraisal), and sell at arm's length. The entire process typically takes 4–6 months from default to sale. Power of sale properties can be good buyer opportunities but come with risks."], checklist: [] },
    { heading: "Foreclosure: The Alternative", paragraphs: ["Foreclosure is more common in BC, Alberta, and Quebec. The lender takes ownership of the property entirely, extinguishing the owner's equity. In foreclosure, if the property sells for more than the mortgage, the lender keeps the surplus (unlike power of sale where surplus goes to the borrower). The process takes longer and involves court proceedings. Buyers purchasing foreclosures get clean title but typically buy as-is with no seller disclosure and sometimes limited access to inspect."], checklist: [] },
    { heading: "Buying a Power of Sale Property", paragraphs: ["Pros: sometimes priced below market, particularly in slow markets or where the lender wants a quick close. Cons: sold strictly as-is — no seller disclosure, no adjustments, no representations. Lender will not repair or renegotiate. Typically shorter conditions periods. Difficult to get full cooperation for inspections — sometimes viewed only with a lockbox and no seller present. Inspect as thoroughly as possible and price any known deficiencies into your offer. Legal review is essential — power of sale purchases have distinct legal requirements."], checklist: [] },
    { heading: "If You're Facing Default", paragraphs: ["Contact your lender immediately — before you miss a payment if possible. Most lenders have hardship programs, payment deferrals, and mortgage modification options for borrowers who communicate early. Options: refinancing, adding missed payments to the mortgage balance, extending amortization. A licensed insolvency trustee can advise on consumer proposals if debt is broader than just the mortgage. CMHC has a homeowner assistance program for insured mortgages. The worst option is doing nothing — defaulting without communicating removes all options."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["If buying: inspect property as thoroughly as possible", "If buying: review all lender documentation with a real estate lawyer", "If buying: price all known deficiencies into offer — no renegotiation after", "If facing default: contact lender before missing a payment", "If facing default: ask about hardship programs explicitly", "If facing default: consult a mortgage broker about refinancing options", "If facing default: consult a licensed insolvency trustee if debt is broader", "Never ignore lender correspondence after missing a payment", "Understand power of sale timeline in your province", "Know that surplus proceeds after mortgage payout belong to you (power of sale)"] },
  ],
  "estate-real-estate": [
    { heading: "The Executor's Role", paragraphs: ["The executor named in the will has the legal authority and responsibility to manage and dispose of estate assets including real property. Before selling, the executor must obtain probate (a court-issued Certificate of Appointment of Estate Trustee) in most provinces for real estate transactions — confirm the requirement with an estate lawyer. Probate validates the will and authorizes the executor to transfer title. The process takes 3–6 months in Ontario, longer in contested estates. No real estate transaction can close without valid authority."], checklist: [] },
    { heading: "Valuation and Tax Implications", paragraphs: ["At death, there is a deemed disposition of the property at fair market value. If the property was the deceased's principal residence, the PRE applies and the capital gain is tax-exempt. If the property was a rental or investment property, capital gains tax applies on the gain from original purchase price to date-of-death fair market value — this is the deceased's tax liability, paid from the estate. Obtain a professional appraisal dated as close to the date of death as possible to establish the adjusted cost base for the estate."], checklist: [] },
    { heading: "Selling Estate Property", paragraphs: ["The executor lists and sells the property as the seller — typically described as 'Estate of [Name], [Executor Name], Executor' on the listing agreement. The property is usually sold as-is — executors cannot warrant the condition or systems of a home they never lived in. Buyers of estate properties should inspect thoroughly. Estate sales can be emotionally complex if beneficiaries disagree on price, timing, or strategy. The executor has legal authority to make decisions — disagreements among beneficiaries are resolved through the estate, not the transaction."], checklist: [] },
    { heading: "When There Is No Will", paragraphs: ["If the deceased died without a will (intestate), a court must appoint an estate administrator before any property can be dealt with. This takes longer than probate for a valid will. The province's intestacy rules determine who inherits — not any verbal instructions or informal letters. This process can take 6–12+ months and is significantly more expensive in legal costs. The single most valuable estate planning step a person can take is having a current, properly signed will — ideally reviewed every 3–5 years."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Confirm executor authority — obtain probate before transaction", "Get professional appraisal as of date of death", "Confirm principal residence vs investment property for tax purposes", "Consult estate lawyer and accountant before listing", "List property as 'Estate of [Name]' on all documents", "Sell as-is — no representations on property condition", "Disclose estate sale nature to buyers and agents", "File terminal tax return for deceased in year of death", "Keep all receipts and documentation for probate accounts", "Obtain clearance certificate from CRA before distributing estate"] },
  ],
  "investment-property-guide": [
    { heading: "Evaluating a Rental Property", paragraphs: ["The key metrics: gross rental yield (annual rent / purchase price), cap rate (net operating income / purchase price after all expenses), and cash-on-cash return (annual cash flow / cash invested including down payment and closing costs). In Toronto and Vancouver condo markets, cap rates are typically 2%–3.5% — low by investment standards. Cash flow on a leveraged condo purchase is often negative. Appreciation has historically compensated for low cap rates in major cities — but past appreciation doesn't guarantee future returns. In secondary markets (Hamilton, Kitchener, Brantford, Kelowna), cap rates of 4%–6% are achievable with proper selection."], checklist: [] },
    { heading: "Financing an Investment Property", paragraphs: ["Investment properties require a minimum 20% down payment — CMHC insurance is not available. Lenders use rental income to help qualify, typically at 50%–80% offset of the rental income (they don't count 100% of rent as income). Mortgage rates on investment properties are typically 0.10%–0.50% higher than owner-occupied rates. Keep your personal and investment property mortgages with different lenders where possible — this preserves refinancing flexibility. Consider a HELOC on your primary residence to fund the investment property down payment — interest on borrowed funds used for income-producing investment is tax-deductible."], checklist: [] },
    { heading: "Due Diligence Before Buying", paragraphs: ["Run a realistic expense model: mortgage payment, property tax, insurance, maintenance (1%–2% of value annually), vacancy allowance (5%–8% of annual rent), property management (8–12% if not self-managing), and capital expenditure reserve ($100–$200/month). If the property doesn't cash flow positively or near-positively at current rent with realistic expenses, you are speculating on appreciation — which is a valid strategy but a different risk profile. Inspect the property thoroughly and review the tenancy status: existing tenant, vacant, or occupied with a pending N12."], checklist: [] },
    { heading: "Long-Term Wealth Building", paragraphs: ["Canadian real estate investment works over time through three mechanisms: mortgage paydown (tenants pay down your mortgage, building equity), appreciation (property values rise with inflation and population growth in strong markets), and rental income growth (rents generally increase over time, improving cash flow). The combination of these three — sometimes called the real estate wealth triangle — has produced strong long-term returns in Canadian markets. The key is buying at a reasonable price, managing expenses tightly, and holding through market cycles."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Calculate cap rate and cash-on-cash return before making offer", "Model all expenses realistically including vacancy and maintenance", "Confirm 20% minimum down payment is available", "Get investment property mortgage pre-approval", "Inspect property thoroughly — no exceptions", "Review existing tenancy status and LTB compliance", "Set up separate bank account for rental income and expenses", "Get landlord insurance before tenant occupies", "File T776 from first year of ownership", "Consider property management — calculate cost vs your time"] },
  ],
};
